import { describe, expect, it } from "vitest";
import ELK from "elkjs/lib/elk.bundled.js";
import definitions from "./fixtures/order-definition.json";
import type { SagaDefinition, SagaTransitionDefinition } from "../src/api/sagaflowApi";
import { conditionLabel, createWorkflowGraph, shortConditionLabel, transitionLabel } from "../src/components/Workflow/workflowMapping";
import { layoutWorkflow } from "../src/components/Workflow/workflowLayout";

// Generated by the existing .NET YAML loader and Dashboard API. A Hosting test verifies it against the real Order YAML.
const order: SagaDefinition = definitions[0];
const transition = (overrides: Partial<SagaTransitionDefinition> = {}): SagaTransitionDefinition => ({ event: "success", nextStep: "completed", when: null, condition: null, else: null, ...overrides });

describe("parsed workflow mapping", () => {
  it("preserves six YAML steps and projects two real conditions plus referenced terminals", () => {
    const graph = createWorkflowGraph(order);
    expect(graph.nodes.filter(node => node.data.kind === "step").map(node => node.data.name)).toEqual([
      "payment", "inventory", "managerNotification", "managerApproval", "shipment", "notification",
    ]);
    expect(graph.nodes).toHaveLength(10);
    expect(graph.nodes.filter(node => node.data.kind === "condition").map(node => node.data.name)).toEqual(["context.totalQuantity > 1000", "steps.managerApproval.result.approved = true"]);
    expect(graph.nodes.filter(node => ["completed", "compensation"].includes(node.data.kind)).map(node => node.id).sort()).toEqual(["terminal:compensation", "terminal:completed"]);
  });

  it("keeps each runtime transition exactly once and omits timeout metadata edges in both modes", () => {
    const graph = createWorkflowGraph(order, { showFailurePaths: true });
    const rules = order.steps.flatMap(step => step.transitions.filter(rule => rule.event !== "timeout"));
    expect(rules).toHaveLength(14);
    for (const rule of rules) expect(graph.edges.filter(edge => edge.data?.transition === rule)).toHaveLength(1);
    expect(graph.edges).toHaveLength(16);
    expect(new Set(graph.edges.map(edge => `${edge.source}/${edge.sourceHandle}`)).size).toBe(16);
    for (const showFailurePaths of [false, true])
      expect(createWorkflowGraph(order, { showFailurePaths }).edges.some(edge => edge.data?.event === "timeout")).toBe(false);
    expect(order.steps.flatMap(step => step.transitions).filter(rule => rule.event === "timeout")).toHaveLength(5);
  });

  it("labels a single condition's matching and declared fallback paths TRUE and FALSE", () => {
    const graph = createWorkflowGraph(order);
    const decision = graph.nodes.find(node => node.id === "condition:inventory:success:0")!;
    expect(decision.data.decision?.sourceStep.name).toBe("inventory");
    expect(graph.edges.find(edge => edge.source === "step:inventory")?.target).toBe(decision.id);
    const edges = graph.edges.filter(edge => edge.source === decision.id);
    expect(edges.map(edge => [edge.target, edge.label])).toEqual([
      ["step:managerNotification", "TRUE"], ["step:shipment", "FALSE"],
    ]);
  });

  it("keeps approval and fallback compensation as separate success transitions without inventing a reject condition", () => {
    const edges = createWorkflowGraph(order).edges.filter(edge => edge.source === "condition:managerApproval:success:0");
    expect(edges.map(edge => [edge.target, edge.label])).toEqual([
      ["step:shipment", "TRUE"], ["terminal:compensation", "FALSE"],
    ]);
  });

  it("preserves compensation commands as step metadata and separates the compensation target", () => {
    const graph = createWorkflowGraph(order);
    expect(graph.nodes.filter(node => node.data.step?.compensation).map(node => node.data.step!.compensation!.command)).toEqual(["RefundPayment", "ReleaseInventory", "CancelShipment"]);
    expect(graph.nodes.find(node => node.id === "terminal:compensation")?.data.kind).toBe("compensation");
    expect(graph.edges.filter(edge => edge.data?.transition?.nextStep === "compensation").every(edge => edge.target === "terminal:compensation")).toBe(true);
    expect(graph.nodes.some(node => node.id === "step:compensation")).toBe(false);
    expect(graph.edges.filter(edge => edge.target === "terminal:compensation")).toHaveLength(1);
  });

  it("hides technical failure paths by default and restores them without changing business compensation", () => {
    const main = createWorkflowGraph(order);
    const complete = createWorkflowGraph(order, { showFailurePaths: true });
    expect(main.edges).toHaveLength(10);
    expect(main.edges.every(edge => edge.data?.event === "success")).toBe(true);
    expect(complete.edges.filter(edge => edge.data?.event === "failure")).toHaveLength(6);
    expect(complete.edges.filter(edge => edge.data?.event === "success")).toEqual(main.edges);
    expect(main.edges.some(edge => edge.source === "step:shipment" && edge.target === "step:notification")).toBe(true);
  });

  it("chains multiple conditions in YAML priority and applies the actual fallback only at the end", () => {
    const fallback = transition({ nextStep: "compensation" });
    const first = transition({ condition: { path: "context.quantity", operator: "greaterThan", value: 1000 } });
    const second = transition({ condition: { path: "context.priority", operator: "equals", value: true } });
    const definition: SagaDefinition = { name: "generic", domain: "returns", version: "1.0", bigPicture: [], steps: [{
      name: "inspect", command: "Inspect", timeoutLimit: null, maxAttempts: 1, compensation: null,
      transitions: [fallback, first, second],
    }] };
    const graph = createWorkflowGraph(definition);
    const conditions = graph.nodes.filter(node => node.data.kind === "condition");
    expect(conditions.map(node => node.data.decision?.transition)).toEqual([first, second]);
    expect(graph.edges.find(edge => edge.source === "step:inspect")?.target).toBe(conditions[0].id);
    expect(graph.edges.find(edge => edge.source === conditions[0].id && edge.data?.kind === "next-rule")?.target).toBe(conditions[1].id);
    expect(conditions[0].data.outgoing.map(port => port.side)).toEqual(["EAST", "SOUTH"]);
    expect(graph.edges.filter(edge => edge.label === "DEFAULT")).toEqual([expect.objectContaining({ source: conditions[1].id, target: "terminal:compensation" })]);
    expect(conditions[0].data.decision?.fallback).toBe(fallback);
    expect(conditions[0].data.decision?.nextRule).toBe(second);
    expect(graph.edges.some(edge => edge.label === "FALSE")).toBe(false);
  });

  it("does not invent a fallback when a conditional outcome has none", () => {
    const definition = structuredClone(order);
    const step = definition.steps.find(step => step.name === "managerApproval")!;
    step.transitions = step.transitions.filter(rule => rule.condition != null);
    const graph = createWorkflowGraph(definition);
    const decision = graph.nodes.find(node => node.data.decision?.sourceStep.name === "managerApproval")!;
    expect(decision.data.decision?.fallback).toBeNull();
    expect(graph.edges.filter(edge => edge.source === decision.id)).toHaveLength(1);
    expect(graph.edges.filter(edge => edge.source === decision.id).some(edge => edge.label === "FALSE")).toBe(false);
  });

  it("projects conditional failure groups only when failure paths are enabled", () => {
    const definition = structuredClone(order);
    const rule = definition.steps[0].transitions.find(rule => rule.event === "failure")!;
    rule.when = "result.recoverable == true";
    expect(createWorkflowGraph(definition).nodes.some(node => node.data.decision?.transition === rule)).toBe(false);
    const condition = createWorkflowGraph(definition, { showFailurePaths: true }).nodes.find(node => node.data.decision?.transition === rule)!;
    expect(condition.data.decision?.transition.when).toBe("result.recoverable == true");
    expect(condition.data.decision?.fallback).toBeNull();
  });

  it.each([
    ["equals", "true", 'context.flag = "true"'],
    ["notEquals", null, "context.flag ≠ null"],
    ["lessThan", 10.5, "context.flag < 10.5"],
  ])("formats %s without type coercion", (operator, value, expected) => {
    expect(conditionLabel(transition({ condition: { path: "context.flag", operator, value } }))).toBe(expected);
  });

  it("uses the exact API comparison literal even when JavaScript would round its numeric value", () => {
    expect(conditionLabel(transition({ condition: { path: "context.quantity", operator: "greaterThan", value: 9007199254740992, valueJson: "9007199254740993" } }))).toBe("context.quantity > 9007199254740993");
  });

  it("shortens only the condition presentation while preserving its full source path and typed value", () => {
    const rule = order.steps.find(step => step.name === "managerApproval")!.transitions[0];
    expect(shortConditionLabel(rule)).toBe("approved = true");
    expect(conditionLabel(rule)).toBe("steps.managerApproval.result.approved = true");
    expect(shortConditionLabel(order.steps[1].transitions[0])).toBe("totalQuantity > 1000");
    expect(shortConditionLabel(transition({ condition: { path: "context.customer.flag", operator: "equals", value: "true" } }))).toBe('flag = "true"');
    expect(shortConditionLabel(transition({ when: "result.available == true" }))).toBe("result.available == true");
  });

  it("preserves legacy expressions and explicit fallback metadata", () => {
    expect(transitionLabel(transition({ when: "result.available == true" }))).toBe("Success · result.available == true");
    expect(transitionLabel(transition({ event: "failure", else: true }))).toBe("Failure · Default");
  });

  it("renders a generic return definition without creating Order steps or relationships from bigPicture references", () => {
    const definition: SagaDefinition = {
      name: "return-flow", domain: "returns", version: "2.0", steps: [{ name: "inspect", command: "InspectReturn", timeoutLimit: null, maxAttempts: 1, compensation: null, transitions: [transition()] }],
      bigPicture: [{ domain: "accounts", process: "reconciliation", endpoint: "https://accounts.example", version: null }],
    };
    const before = JSON.stringify(definition);
    const graph = createWorkflowGraph(definition);
    expect(graph.nodes.map(node => node.id)).toEqual(["step:inspect", "terminal:completed"]);
    expect(graph.edges).toHaveLength(1);
    expect(JSON.stringify(definition)).toBe(before);
  });

  it("does not invent a node for an undeclared transition target", () => {
    const definition = structuredClone(order);
    definition.steps[0].transitions[0].nextStep = "missing";
    expect(() => createWorkflowGraph(definition)).toThrow("Unknown transition target 'missing'");
  });

  it.each([false, true])("uses compact left-to-right ELK layout with distinct ports (failures: %s)", async showFailurePaths => {
    const elk = new ELK();
    const graph = await layoutWorkflow(createWorkflowGraph(order, { showFailurePaths }), elk);
    for (const node of graph.nodes) {
      expect(Number.isFinite(node.position.x) && Number.isFinite(node.position.y)).toBe(true);
      const ports = [...node.data.incoming, ...node.data.outgoing];
      expect(new Set(ports.map(port => `${port.x}:${port.y}`)).size).toBe(ports.length);
      for (const port of ports) {
        expect(Number.isFinite(port.x) && Number.isFinite(port.y)).toBe(true);
        if (port.side === "EAST") expect(port.x, `${node.id}/${port.id}`).toBeGreaterThanOrEqual(node.width! - 2);
        if (port.side === "WEST") expect(port.x).toBeLessThanOrEqual(0);
        if (port.side === "NORTH") expect(port.y).toBeLessThanOrEqual(0);
        if (port.side === "SOUTH") expect(port.y, JSON.stringify({ node: node.id, ports })).toBeGreaterThanOrEqual(node.height! - 2);
      }
      for (const other of graph.nodes.filter(other => other.id !== node.id)) {
        const overlap = node.position.x < other.position.x + other.width! && node.position.x + node.width! > other.position.x && node.position.y < other.position.y + other.height! && node.position.y + node.height! > other.position.y;
        expect(overlap).toBe(false);
      }
      if (node.data.kind === "condition") {
        expect(node.data.incoming).toEqual([expect.objectContaining({ side: "WEST", y: node.height! / 2 })]);
        expect(Math.abs(node.data.incoming[0].x!)).toBe(0);
        expect(node.data.outgoing).toEqual([
          expect.objectContaining({ side: "EAST", x: node.width, y: node.height! / 2 }),
          expect.objectContaining({ side: "SOUTH", x: node.width! / 2, y: node.height }),
        ]);
      }
    }
    const payment = graph.nodes.find(node => node.id === "step:payment")!;
    const inventory = graph.nodes.find(node => node.id === "step:inventory")!;
    expect(inventory.position.x).toBeGreaterThan(payment.position.x);
    expect(inventory.position.x - payment.position.x - payment.width!).toBeLessThan(160);
    expect(graph.edges).toHaveLength(showFailurePaths ? 16 : 10);
  });
});
